package vn.svframe.lively.persistence;
import com.google.gson.*;import vn.svframe.lively.world.SemanticStructureRegistry;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;public final class StructureTransferStore{private final Path directory;private final Gson gson=new GsonBuilder().setPrettyPrinting().create();public StructureTransferStore(Path d){directory=d;}public Path exportStructure(SemanticStructureRegistry.Structure s){String name=safe(s.id())+".json";Path file=directory.resolve(name);try{Files.createDirectories(directory);Path tmp=file.resolveSibling(name+".tmp");Files.writeString(tmp,gson.toJson(s),StandardCharsets.UTF_8);try{Files.move(tmp,file,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(IOException ignored){Files.move(tmp,file,StandardCopyOption.REPLACE_EXISTING);}return file;}catch(IOException e){throw new IllegalStateException("structure export failed",e);}}public Optional<SemanticStructureRegistry.Structure>importStructure(String name){Path file=directory.resolve(safe(name)+".json").normalize();if(!file.startsWith(directory.normalize())||!Files.isRegularFile(file))return Optional.empty();try{if(Files.size(file)>1048576L)throw new IOException("structure file too large");return Optional.ofNullable(gson.fromJson(Files.readString(file,StandardCharsets.UTF_8),SemanticStructureRegistry.Structure.class));}catch(Exception e){throw new IllegalStateException("structure import failed",e);}}private static String safe(String v){String s=v==null?"":v.trim().replaceAll("[^A-Za-z0-9_.-]","_");if(s.isBlank()||s.length()>128)throw new IllegalArgumentException("invalid structure file name");return s;}}
